import type { NewsMetro } from "@/db/generated/client";
import { prisma } from "@/db";
import { z } from "zod";

const searchSchema = z.object({
  query: z.string().min(1),
  limit: z.number().int().min(1).max(50).optional(),
});

const nearestSchema = z.object({
  latitude: z.number().min(-90).max(90),
  longitude: z.number().min(-180).max(180),
  maxKm: z.number().positive().max(500).optional(),
});

export type NewsMetroSearchInput = z.input<typeof searchSchema>;
export type NewsMetroNearestInput = z.input<typeof nearestSchema>;

const METRO_CACHE_TTL_MS = 5 * 60 * 1000;
let metroCache: NewsMetro[] | null = null;
let metroCacheExpiresAt = 0;

async function loadAllNewsMetros(): Promise<NewsMetro[]> {
  if (metroCache && Date.now() < metroCacheExpiresAt) {
    return metroCache;
  }
  metroCache = await prisma.newsMetro.findMany({ orderBy: { name: "asc" } });
  metroCacheExpiresAt = Date.now() + METRO_CACHE_TTL_MS;
  return metroCache;
}

export function invalidateNewsMetroCache(): void {
  metroCache = null;
  metroCacheExpiresAt = 0;
}

function normalizeQuery(query: string): string {
  return query.trim().toLowerCase();
}

function metroMatchesPrefix(metro: NewsMetro, q: string): boolean {
  if (metro.name.toLowerCase().startsWith(q)) {
    return true;
  }
  if (metro.id.startsWith(q.replace(/\s+/g, "-"))) {
    return true;
  }
  return metro.aliases.some((alias) => alias.toLowerCase().startsWith(q));
}

function metroMatchesExact(metro: NewsMetro, q: string): boolean {
  if (metro.name.toLowerCase() === q) {
    return true;
  }
  return metro.aliases.some((alias) => alias.toLowerCase() === q);
}

export async function getNewsMetroById(id: string) {
  return await prisma.newsMetro.findUnique({ where: { id } });
}

export async function searchNewsMetros(input: NewsMetroSearchInput) {
  const parsed = searchSchema.parse(input);
  const q = normalizeQuery(parsed.query);
  const limit = parsed.limit ?? 25;
  const all = await loadAllNewsMetros();
  return all.filter((metro) => metroMatchesPrefix(metro, q)).slice(0, limit);
}

export async function findNewsMetroByExactNameOrAlias(text: string) {
  const q = normalizeQuery(text);
  if (!q) {
    return null;
  }
  const all = await loadAllNewsMetros();
  return all.find((metro) => metroMatchesExact(metro, q)) ?? null;
}

function haversineKm(
  lat: number,
  lng: number,
  metro: Pick<NewsMetro, "latitude" | "longitude">,
): number {
  const rad = (d: number) => (d * Math.PI) / 180;
  const dLat = rad(metro.latitude - lat);
  const dLng = rad(metro.longitude - lng);
  const a =
    Math.sin(dLat / 2) ** 2 +
    Math.cos(rad(lat)) * Math.cos(rad(metro.latitude)) * Math.sin(dLng / 2) ** 2;
  return 6371 * 2 * Math.asin(Math.sqrt(a));
}

export async function findNearestNewsMetro(input: NewsMetroNearestInput) {
  const parsed = nearestSchema.parse(input);
  const maxKm = parsed.maxKm ?? 150;
  const all = await loadAllNewsMetros();
  let best: NewsMetro | undefined;
  let bestKm = Infinity;
  for (const metro of all) {
    const distanceKm = haversineKm(parsed.latitude, parsed.longitude, metro);
    if (distanceKm < bestKm) {
      best = metro;
      bestKm = distanceKm;
    }
  }
  if (!best || bestKm > maxKm) {
    return null;
  }
  return { metro: best, distanceKm: bestKm };
}

export async function upsertNewsMetroSeed(
  row: Omit<NewsMetro, never> | Parameters<typeof prisma.newsMetro.upsert>[0]["create"],
) {
  return await prisma.newsMetro.upsert({
    where: { id: row.id },
    create: row,
    update: {
      name: row.name,
      aliases: row.aliases,
      country: row.country,
      countryCode: row.countryCode,
      region: row.region,
      latitude: row.latitude,
      longitude: row.longitude,
      timezone: row.timezone,
      lang: row.lang,
    },
  });
}

import type { NewsMetro } from "@/db/generated/client";
import {
  findNearestNewsMetro,
  findNewsMetroByExactNameOrAlias,
  searchNewsMetros,
} from "@/repositories/newsMetro";

export type SerializedNewsMetro = {
  id: string;
  name: string;
  aliases: string[];
  country: string;
  countryCode: string;
  region: string;
  latitude: number;
  longitude: number;
  timezone: string;
  lang: string;
  /** Stored on news requests (city + country). */
  label: string;
};

export function formatNewsMetroLabel(
  metro: Pick<NewsMetro, "name" | "country">,
): string {
  return `${metro.name}, ${metro.country}`;
}

export function serializeNewsMetro(metro: NewsMetro): SerializedNewsMetro {
  return {
    id: metro.id,
    name: metro.name,
    aliases: metro.aliases,
    country: metro.country,
    countryCode: metro.countryCode,
    region: metro.region,
    latitude: metro.latitude,
    longitude: metro.longitude,
    timezone: metro.timezone,
    lang: metro.lang,
    label: formatNewsMetroLabel(metro),
  };
}

/** Match free text to a metro by exact name, alias, or stored label prefix. */
export async function resolveNewsMetroFromLocationText(
  location: string,
): Promise<SerializedNewsMetro | null> {
  const trimmed = location.trim();
  if (!trimmed) {
    return null;
  }

  const exact = await findNewsMetroByExactNameOrAlias(trimmed);
  if (exact) {
    return serializeNewsMetro(exact);
  }

  const primary = trimmed.split(",")[0]?.trim() ?? trimmed;
  if (primary !== trimmed) {
    const byPrimary = await findNewsMetroByExactNameOrAlias(primary);
    if (byPrimary) {
      return serializeNewsMetro(byPrimary);
    }
  }

  const hits = await searchNewsMetros({ query: primary, limit: 1 });
  const first = hits[0];
  if (!first) {
    return null;
  }
  return serializeNewsMetro(first);
}

export async function resolveCoordsFromNewsMetroLocation(
  location: string,
): Promise<{ latitude: number; longitude: number } | null> {
  const metro = await resolveNewsMetroFromLocationText(location);
  if (!metro) {
    return null;
  }
  return { latitude: metro.latitude, longitude: metro.longitude };
}

export async function resolveNearestSerializedNewsMetro(
  latitude: number,
  longitude: number,
  maxKm?: number,
): Promise<(SerializedNewsMetro & { distanceKm: number }) | null> {
  const hit = await findNearestNewsMetro({ latitude, longitude, maxKm });
  if (!hit) {
    return null;
  }
  return {
    ...serializeNewsMetro(hit.metro),
    distanceKm: hit.distanceKm,
  };
}

/** SerpApi Google News params for a metro's local news. */
export function localNewsParamsForMetro(
  metro: Pick<SerializedNewsMetro, "name" | "aliases" | "countryCode" | "lang">,
  englishOnly = true,
) {
  const names = [metro.name, ...metro.aliases.filter((alias) => alias.length > 3)].map(
    (name) => `"${name}"`,
  );
  return {
    engine: "google_news" as const,
    q: names.join(" OR "),
    gl: metro.countryCode,
    hl: englishOnly ? "en" : metro.lang,
  };
}

