import { DateTime } from "luxon";
import type { NewsletterFrequency } from "@/db/generated/client";

export type ScheduleInput = {
  frequency: NewsletterFrequency;
  sendTimeLocal: string;
  timezone: string;
  dayOfWeek?: number | null;
  dayOfMonth?: number | null;
  from?: Date;
};

function parseSendTime(sendTimeLocal: string): { hour: number; minute: number } {
  const match = /^(\d{1,2}):(\d{2})$/.exec(sendTimeLocal.trim());
  if (!match) {
    throw new Error("sendTimeLocal must be HH:mm");
  }
  const hour = Number.parseInt(match[1]!, 10);
  const minute = Number.parseInt(match[2]!, 10);
  if (hour < 0 || hour > 23 || minute < 0 || minute > 59) {
    throw new Error("sendTimeLocal out of range");
  }
  return { hour, minute };
}

function withSendTime(dt: DateTime, sendTimeLocal: string): DateTime {
  const { hour, minute } = parseSendTime(sendTimeLocal);
  return dt.set({ hour, minute, second: 0, millisecond: 0 });
}

function isWeekday(dt: DateTime): boolean {
  return dt.weekday >= 1 && dt.weekday <= 5;
}

function clampMonthlyDay(dt: DateTime, dayOfMonth: number): DateTime {
  const day = Math.min(dayOfMonth, dt.daysInMonth ?? dayOfMonth);
  return dt.set({ day });
}

/** Next UTC instant when a newsletter should run (timezone/DST aware). */
export function computeNextRun(input: ScheduleInput): Date {
  const zone = input.timezone;
  const { hour, minute } = parseSendTime(input.sendTimeLocal);
  let cursor = DateTime.fromJSDate(input.from ?? new Date(), { zone }).plus({
    minutes: 1,
  });

  for (let i = 0; i < 400; i++) {
    let candidate = withSendTime(cursor, input.sendTimeLocal);
    if (candidate <= DateTime.fromJSDate(input.from ?? new Date(), { zone })) {
      candidate = candidate.plus({ days: 1 });
    }

    if (input.frequency === "DAILY") {
      if (candidate > DateTime.now().setZone(zone)) {
        return candidate.toUTC().toJSDate();
      }
      cursor = candidate.plus({ days: 1 });
      continue;
    }

    if (input.frequency === "WEEKDAYS") {
      while (!isWeekday(candidate)) {
        candidate = candidate.plus({ days: 1 });
      }
      if (candidate > DateTime.now().setZone(zone)) {
        return candidate.toUTC().toJSDate();
      }
      cursor = candidate.plus({ days: 1 });
      continue;
    }

    if (input.frequency === "WEEKLY") {
      const dow = input.dayOfWeek ?? 1;
      let weekly = candidate.set({ weekday: dow as 1 | 2 | 3 | 4 | 5 | 6 | 7 });
      weekly = weekly.set({ hour, minute, second: 0, millisecond: 0 });
      if (weekly <= DateTime.now().setZone(zone)) {
        weekly = weekly.plus({ weeks: 1 });
      }
      return weekly.toUTC().toJSDate();
    }

    if (input.frequency === "MONTHLY") {
      const dom = input.dayOfMonth ?? 1;
      let monthly = clampMonthlyDay(candidate.startOf("month"), dom).set({
        hour,
        minute,
        second: 0,
        millisecond: 0,
      });
      if (monthly <= DateTime.now().setZone(zone)) {
        monthly = clampMonthlyDay(monthly.plus({ months: 1 }).startOf("month"), dom).set({
          hour,
          minute,
          second: 0,
          millisecond: 0,
        });
      }
      return monthly.toUTC().toJSDate();
    }

    cursor = candidate.plus({ days: 1 });
  }

  throw new Error("computeNextRun: could not find next run within horizon");
}

export type NewsWindow = {
  /** ISO date YYYY-MM-DD for the edition's news day in the newsletter timezone. */
  date: string;
  periodKey: string;
  windowStart: Date;
  windowEnd: Date;
};

/** Calendar window for shared edition content for a scheduled send. */
export function newsWindow(
  scheduledFor: Date,
  timezone: string,
  frequency: NewsletterFrequency,
): NewsWindow {
  const zoned = DateTime.fromJSDate(scheduledFor, { zone: timezone });
  const date = zoned.toISODate();
  if (!date) {
    throw new Error("Invalid scheduledFor for newsWindow");
  }

  const windowStart = zoned.startOf("day").toUTC().toJSDate();
  const windowEnd = zoned.endOf("day").toUTC().toJSDate();
  const periodKey =
    frequency === "MONTHLY"
      ? zoned.toFormat("yyyy-MM")
      : frequency === "WEEKLY"
        ? `${zoned.weekYear}-W${String(zoned.weekNumber).padStart(2, "0")}`
        : date;

  return { date, periodKey, windowStart, windowEnd };
}

import { NEWS_METRO_SEEDS } from "@/config/newsMetros";

const METRO_BY_NAME = new Map<string, string>();
const METRO_BY_ALIAS = new Map<string, string>();

for (const metro of NEWS_METRO_SEEDS) {
  METRO_BY_NAME.set(metro.name.trim().toLowerCase(), metro.id);
  for (const alias of metro.aliases) {
    METRO_BY_ALIAS.set(alias.trim().toLowerCase(), metro.id);
  }
  METRO_BY_ALIAS.set(metro.id, metro.id);
}

/** Map free-text location to a stable metro id when possible. */
export function normalizeLocationToMetroId(location: string | null | undefined): string | null {
  if (!location?.trim()) {
    return null;
  }
  const primary = location.split(",")[0]?.trim().toLowerCase() ?? "";
  if (!primary) {
    return null;
  }
  return (
    METRO_BY_NAME.get(primary) ??
    METRO_BY_ALIAS.get(primary) ??
    null
  );
}

export function listKnownMetroIds(): string[] {
  return NEWS_METRO_SEEDS.map((row) => row.id);
}

