  await deactivateNewsletter(id);
  return new NextResponse(
    "<html><body><h1>Unsubscribed</h1><p>You will no longer receive this newsletter.</p></body></html>",
    { headers: { "Content-Type": "text/html; charset=utf-8" } },
  );
}

