import { NextResponse, type NextRequest } from "next/server";
import { z } from "zod";
import type { InstrumentSuggestion } from "@/app/api/instruments/suggest/route";
import { requireAuthenticatedUser } from "@/lib/auth";
import { ETF_EQ_SEGMENTS, searchEtfsByName } from "@/repositories/instrument";

const SUGGESTION_LIMIT = 10;

const etfEqSegmentSchema = z.enum(ETF_EQ_SEGMENTS);

const suggestQuerySchema = z.object({
  q: z.string().trim().min(1, "q is required"),
  segment: etfEqSegmentSchema.optional(),
});

export async function GET(request: NextRequest) {
  const user = await requireAuthenticatedUser();
  if (!user) {
    return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
  }

  const { searchParams } = request.nextUrl;
  const parsed = suggestQuerySchema.safeParse({
    q: searchParams.get("q") ?? "",
    segment: searchParams.get("segment") ?? undefined,
  });
  if (!parsed.success) {
    return NextResponse.json(
      { error: "Validation failed", details: z.treeifyError(parsed.error) },
      { status: 400 },
    );
  }

  const instruments = await searchEtfsByName({
    query: parsed.data.q,
    segment: parsed.data.segment,
    limit: SUGGESTION_LIMIT,
  });

  const suggestions: InstrumentSuggestion[] = instruments.map((row) => ({
    instrumentKey: row.instrumentKey,
    name: row.name,
    shortName: row.shortName,
    tradingSymbol: row.tradingSymbol,
    exchange: row.exchange,
    segment: row.segment,
    instrumentType: row.instrumentType,
  }));

  return NextResponse.json({ suggestions });
}

"use client";

import { useEffect, useId, useState } from "react";
import { Input } from "@/components/ui/input";
import { cn } from "@/lib/utils";
import type { InstrumentSuggestion } from "@/app/api/instruments/suggest/route";

const DEBOUNCE_MS = 250;

type EtfSearchProps = {
  onSelect?: (instrument: InstrumentSuggestion) => void;
  onClear?: () => void;
};

export function EtfSearch({ onSelect, onClear }: EtfSearchProps) {
  const listId = useId();
  const [query, setQuery] = useState("");
  const [suggestions, setSuggestions] = useState<InstrumentSuggestion[]>([]);
  const [isLoading, setIsLoading] = useState(false);
  const [isOpen, setIsOpen] = useState(false);
  const [activeIndex, setActiveIndex] = useState(-1);
  const [selected, setSelected] = useState<InstrumentSuggestion | null>(null);

  useEffect(() => {
    const q = query.trim();
    if (!q || q === selected?.name) return;

    const controller = new AbortController();
    const timer = setTimeout(async () => {
      setIsLoading(true);
      try {
        const params = new URLSearchParams({ q });
        const res = await fetch(`/api/instruments/etfs/suggest?${params}`, {
          signal: controller.signal,
        });
        if (!res.ok) throw new Error(`Request failed: ${res.status}`);
        const data: { suggestions: InstrumentSuggestion[] } = await res.json();
        setSuggestions(data.suggestions);
        setActiveIndex(-1);
        setIsOpen(true);
      } catch (error) {
        if (!controller.signal.aborted) {
          console.error(error);
          setSuggestions([]);
        }
      } finally {
        if (!controller.signal.aborted) setIsLoading(false);
      }
    }, DEBOUNCE_MS);

    return () => {
      clearTimeout(timer);
      controller.abort();
    };
  }, [query, selected]);

  function handleSelect(instrument: InstrumentSuggestion) {
    setSelected(instrument);
    setQuery(instrument.name);
    setSuggestions([]);
    setIsOpen(false);
    onSelect?.(instrument);
  }

  function handleKeyDown(event: React.KeyboardEvent<HTMLInputElement>) {
    if (!isOpen || suggestions.length === 0) return;

    if (event.key === "ArrowDown") {
      event.preventDefault();
      setActiveIndex((i) => (i + 1) % suggestions.length);
    } else if (event.key === "ArrowUp") {
      event.preventDefault();
      setActiveIndex((i) => (i <= 0 ? suggestions.length - 1 : i - 1));
    } else if (event.key === "Enter" && activeIndex >= 0) {
      event.preventDefault();
      handleSelect(suggestions[activeIndex]);
    } else if (event.key === "Escape") {
      setIsOpen(false);
    }
  }

  const showList = isOpen && query.trim().length > 0;

  return (
    <div className="relative w-full">
      <Input
        type="text"
        role="combobox"
        aria-expanded={showList}
        aria-controls={listId}
        aria-autocomplete="list"
        placeholder="Search an ETF by name…"
        value={query}
        onChange={(event) => {
          const value = event.target.value;
          setQuery(value);
          if (selected) {
            setSelected(null);
            onClear?.();
          }
          if (!value.trim()) {
            setSuggestions([]);
            setIsLoading(false);
          }
        }}
        onFocus={() => suggestions.length > 0 && setIsOpen(true)}
        onBlur={() => setIsOpen(false)}
        onKeyDown={handleKeyDown}
      />

      {showList && (
        <ul
          id={listId}
          role="listbox"
          className="absolute z-20 mt-1 max-h-80 w-full overflow-y-auto rounded-md border bg-popover p-1 text-popover-foreground shadow-md"
        >
          {isLoading && suggestions.length === 0 ? (
            <li className="px-2.5 py-2 text-sm text-muted-foreground">
              Searching…
            </li>
          ) : suggestions.length === 0 ? (
            <li className="px-2.5 py-2 text-sm text-muted-foreground">
              No matches
            </li>
          ) : (
            suggestions.map((instrument, index) => (
              <li
                key={instrument.instrumentKey}
                role="option"
                aria-selected={index === activeIndex}
                onMouseDown={(event) => event.preventDefault()}
                onClick={() => handleSelect(instrument)}
                onMouseEnter={() => setActiveIndex(index)}
                className={cn(
                  "flex cursor-pointer items-center justify-between gap-3 rounded-sm px-2.5 py-2 text-sm",
                  index === activeIndex && "bg-accent text-accent-foreground",
                )}
              >
                <span className="truncate">{instrument.name}</span>
                <span className="shrink-0 text-xs text-muted-foreground">
                  {instrument.tradingSymbol} · {instrument.exchange}
                </span>
              </li>
            ))
          )}
        </ul>
      )}
    </div>
  );
}

