type UnsubscribePageProps = {
  searchParams: Promise<{ id?: string; token?: string }>;
};

function InvalidUnsubscribeLink() {
  return (
    <div className="mx-auto flex min-h-[50vh] max-w-lg flex-col justify-center px-4 py-12">
      <Card>
        <CardHeader>
          <CardTitle>Invalid unsubscribe link</CardTitle>
          <CardDescription>
            This link may be expired, incomplete, or already used. Open the
            latest email from your newsletter and use the unsubscribe link
            there, or contact support.
          </CardDescription>
        </CardHeader>
        <CardContent>
          <Button variant="outline" render={<Link href="/" />}>
            Go to homepage
          </Button>
        </CardContent>
      </Card>
    </div>
  );
}

export default async function UnsubscribePage({
  searchParams,
}: UnsubscribePageProps) {
  const { id, token } = await searchParams;

  if (!id?.trim() || !token?.trim()) {
    return <InvalidUnsubscribeLink />;
  }

  let tokenValid = false;
  try {
    tokenValid = verifyNewsletterUnsubscribeToken(id, token);
  } catch {
    tokenValid = false;
  }

  if (!tokenValid) {
    return <InvalidUnsubscribeLink />;
  }

  const newsletter = await getNewsletterById(id);
  if (!newsletter) {
    return <InvalidUnsubscribeLink />;
  }

  return (
    <UnsubscribeNewsletterClient
      newsletterId={id}
      token={token}
      newsletter={{
        name: newsletter.name,
        email: newsletter.email,
        scope: newsletter.scope,
        storyCount: newsletter.storyCount,
        location: newsletter.location,
        frequency: newsletter.frequency,
        sendTimeLocal: newsletter.sendTimeLocal,
        timezone: newsletter.timezone,
        isActive: newsletter.isActive,
      }}
    />
  );
}

import { deactivateNewsletter } from "@/repositories/newsletter";
import { verifyNewsletterUnsubscribeToken } from "@/lib/newsletter/unsubscribeToken";
import { NextResponse } from "next/server";

/** Confirmed unsubscribe (after UI confirmation). GET is handled by `page.tsx`. */
export async function POST(request: Request) {
  const url = new URL(request.url);
  const id = url.searchParams.get("id");
  const token = url.searchParams.get("token");
  if (!id || !token || !verifyNewsletterUnsubscribeToken(id, token)) {
    return NextResponse.json({ error: "Invalid token" }, { status: 400 });
  }
  await deactivateNewsletter(id);
  return NextResponse.json({ ok: true });
}

